/* Runtime CSS patches extracted from v78 in original cascade order. */

/* ===== v74-step1-main-galaxy-ui ===== */
:root{
  --v74-panel:linear-gradient(180deg, rgba(8,18,36,.95), rgba(4,10,20,.98));
  --v74-card:linear-gradient(180deg, rgba(9,19,38,.88), rgba(4,10,20,.93));
  --v74-line:rgba(72, 224, 255, .24);
  --v74-line-strong:rgba(102, 234, 255, .44);
  --v74-cyan:#67e8ff;
  --v74-cyan-strong:#1ddaff;
  --v74-purple:#a277ff;
  --v74-text:#eef9ff;
  --v74-sub:#a2c6dd;
  --v74-shadow:0 18px 42px rgba(2,6,23,.42), 0 0 20px rgba(6,182,255,.06);
}
/* STEP 1 ONLY: Main menu + Galaxy map */
#menu{
  background:
    radial-gradient(circle at 50% 18%, rgba(19,64,132,.28), transparent 28%),
    radial-gradient(circle at 85% 14%, rgba(168,85,247,.12), transparent 22%),
    radial-gradient(circle at 15% 86%, rgba(14,165,233,.10), transparent 18%),
    rgba(1,4,10,.92) !important;
}
#menu .card{
  width:min(1180px, calc(100vw - 28px)) !important;
  max-height:calc(100dvh - 32px);
  overflow:auto;
  padding:34px 30px 28px !important;
  border-radius:30px !important;
  border:1px solid var(--v74-line) !important;
  background:var(--v74-panel) !important;
  box-shadow:inset 0 0 0 1px rgba(119,245,255,.03), var(--v74-shadow) !important;
  position:relative;
}
#menu .card::before{
  content:''; position:absolute; inset:14px; pointer-events:none;
  border:1px solid rgba(70,224,255,.16); border-radius:22px;
  clip-path:polygon(0 20px, 20px 20px, 20px 0, calc(100% - 20px) 0, calc(100% - 20px) 20px, 100% 20px, 100% calc(100% - 20px), calc(100% - 20px) calc(100% - 20px), calc(100% - 20px) 100%, 20px 100%, 20px calc(100% - 20px), 0 calc(100% - 20px));
  opacity:.9;
}
#menu h1{
  color:var(--v74-text) !important;
  font-family:'Orbitron', Pretendard, sans-serif !important;
  font-size:clamp(28px, 4vw, 46px) !important;
  letter-spacing:.14em !important;
  margin-bottom:8px !important;
  text-shadow:0 0 16px rgba(29,218,255,.12);
}
#menu .menuSub{
  color:var(--v74-cyan) !important;
  font-family:'Orbitron', Pretendard, sans-serif !important;
  letter-spacing:.32em !important;
  font-size:12px !important;
  margin-bottom:18px !important;
}
#menu p,
#menu .sub,
#menu .offlineMetaStory{
  color:var(--v74-sub) !important;
}
#menu .menuGrid{
  display:grid !important;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:14px;
  margin-top:18px;
}
#menu .info,
#offlineMenuPanel{
  background:var(--v74-card) !important;
  border:1px solid rgba(67,215,255,.16) !important;
  border-radius:22px !important;
  box-shadow:inset 0 0 0 1px rgba(119,245,255,.02), 0 0 16px rgba(6,182,255,.04) !important;
}
#menu .info{padding:16px 18px !important;}
#menu .info b,
#offlineMenuPanel .offlineMetaTitle,
#offlineMenuPanel .offlineMetaShard{color:var(--v74-text) !important;}
#offlineMenuPanel .offlineMetaTitle{
  font-family:'Orbitron', Pretendard, sans-serif !important;
  letter-spacing:.12em !important;
  color:var(--v74-cyan) !important;
}
#menu .menuActionRow{
  display:flex !important; flex-wrap:wrap; gap:12px; justify-content:center;
  margin-top:22px !important;
}
#menu button,
#menu .secondaryAction{
  min-height:58px !important;
  padding:14px 28px !important;
  border-radius:18px !important;
  font-family:'Orbitron','Noto Sans KR',sans-serif !important;
  font-size:15px !important;
  color:var(--v74-text) !important;
  border:1px solid rgba(64,210,255,.24) !important;
  background:linear-gradient(180deg, rgba(9,18,36,.96), rgba(4,10,22,.98)) !important;
  box-shadow:inset 0 0 0 1px rgba(112,238,255,.04), 0 0 18px rgba(31,212,255,.05) !important;
  position:relative; overflow:hidden;
}
#menu button::before{
  content:''; position:absolute; inset:0; pointer-events:none;
  background:radial-gradient(circle at 14% 18%, rgba(255,255,255,.10), transparent 18%), linear-gradient(90deg, rgba(38,218,255,.14), transparent 28%, transparent 72%, rgba(191,114,255,.14));
}
#startBtn{
  background:linear-gradient(90deg, rgba(89,228,255,.98), rgba(108,118,255,.96), rgba(163,92,255,.96)) !important;
  color:white !important;
  border-color:rgba(215,243,255,.36) !important;
  box-shadow:inset 0 0 0 1px rgba(255,255,255,.16), 0 0 24px rgba(120,168,255,.18) !important;
}
#menu button:hover{transform:translateY(-1px); border-color:rgba(104,229,255,.44) !important;}

/* Galaxy map shell and cards only */
#galaxyMap .galaxyBackBtn,
#galaxyMap .galaxyStatus,
#galaxyInfoPanel,
#galaxyMap .galaxyEnterBtn{
  background:var(--v74-panel) !important;
  border:1px solid var(--v74-line) !important;
  box-shadow:inset 0 0 0 1px rgba(119,245,255,.03), var(--v74-shadow) !important;
}
#galaxyMap .galaxyBackBtn,
#galaxyMap .galaxyEnterBtn{
  font-family:'Orbitron','Noto Sans KR',sans-serif !important;
  color:var(--v74-text) !important;
  border-radius:18px !important;
}
#galaxyMap .galaxyBackBtn{
  top:24px !important; left:20px !important; padding:10px 14px !important;
}
#galaxyMap .galaxyTopTitle{
  top:26px !important;
  font-family:'Orbitron', Pretendard, sans-serif !important;
  font-size:clamp(18px, 2.4vw, 28px) !important;
  letter-spacing:.22em !important;
  color:var(--v74-cyan) !important;
  text-shadow:0 0 16px rgba(29,218,255,.12);
}
#galaxyMap .galaxyStatus{
  top:72px !important;
  border-radius:18px !important;
  padding:10px 14px !important;
  color:var(--v74-sub) !important;
  backdrop-filter:blur(10px);
}
#galaxyMap .galaxyStatus b{color:var(--v74-text) !important;}
#galaxyMap .galaxySceneWrap{
  border:1px solid rgba(67,215,255,.16) !important;
  border-radius:28px !important;
  box-shadow:inset 0 0 0 1px rgba(119,245,255,.02), 0 0 18px rgba(6,182,255,.04) !important;
  overflow:hidden;
}
#galaxyMap .galaxySceneWrap::before{
  content:''; position:absolute; inset:12px; pointer-events:none;
  border:1px solid rgba(67,215,255,.10); border-radius:22px;
  clip-path:polygon(0 16px, 16px 16px, 16px 0, calc(100% - 16px) 0, calc(100% - 16px) 16px, 100% 16px, 100% calc(100% - 16px), calc(100% - 16px) calc(100% - 16px), calc(100% - 16px) 100%, 16px 100%, 16px calc(100% - 16px), 0 calc(100% - 16px));
}
#galaxyMap .galaxyRouteSvg .routeBase{stroke:rgba(148,163,184,.16) !important;}
#galaxyMap .galaxyRouteSvg .routeGlow{filter:drop-shadow(0 0 8px rgba(103,232,249,.18));}
#galaxyMap .galaxyNodeLabel,
#galaxyMap .galaxyNodeBadge,
#galaxyMap .galaxyLockMark{ text-shadow:0 0 10px rgba(0,0,0,.35); }
#galaxyInfoPanel{
  border-radius:26px !important;
  color:var(--v74-sub) !important;
}
#galaxyInfoPanel .galaxyInfoHead{
  border-bottom:1px solid rgba(67,215,255,.12) !important;
  padding-bottom:10px; margin-bottom:10px;
}
#galaxyInfoPanel .galaxyInfoTitle{
  font-family:'Orbitron', Pretendard, sans-serif !important;
  color:var(--v74-text) !important;
}
#galaxyInfoPanel .galaxyInfoTitle small,
#galaxyMap .galaxyTag,
#galaxyInfoPanel .galaxyInfoState b{ color:var(--v74-cyan) !important; }
#galaxyMap .galaxyTag{
  background:linear-gradient(180deg, rgba(9,19,38,.88), rgba(4,10,20,.93)) !important;
  border:1px solid rgba(67,215,255,.16) !important;
  border-radius:999px !important;
}
#galaxyInfoPanel .galaxyMetaCard{
  background:var(--v74-card) !important;
  border:1px solid rgba(67,215,255,.16) !important;
  border-radius:18px !important;
  box-shadow:inset 0 0 0 1px rgba(119,245,255,.02), 0 0 14px rgba(6,182,255,.03) !important;
}
#galaxyInfoPanel .galaxyMetaCard small{color:var(--v74-cyan) !important; font-family:'Orbitron', Pretendard, sans-serif !important;}
#galaxyInfoPanel .galaxyMetaCard b{color:var(--v74-text) !important;}
#galaxyInfoPanel .galaxyMetaCard span,
#galaxyInfoPanel .galaxyInfoBody{color:var(--v74-sub) !important;}
#galaxyMap .galaxyEnterBtn{
  background:linear-gradient(90deg, rgba(89,228,255,.98), rgba(108,118,255,.96), rgba(163,92,255,.96)) !important;
  color:white !important;
  border-color:rgba(215,243,255,.36) !important;
  box-shadow:inset 0 0 0 1px rgba(255,255,255,.16), 0 0 24px rgba(120,168,255,.18) !important;
}
#galaxyMap .galaxyBackBtn:hover,
#galaxyMap .galaxyEnterBtn:hover{transform:translateY(-1px);}

@media (max-width: 900px){
  #menu .menuGrid{grid-template-columns:1fr !important;}
}
@media (max-width: 768px){
  #menu .card{padding:24px 18px 20px !important; border-radius:24px !important;}
  #menu h1{font-size:26px !important; letter-spacing:.1em !important;}
  #menu .menuSub{letter-spacing:.24em !important;}
  #menu button{min-height:54px !important; font-size:14px !important;}
  #galaxyMap .galaxyBackBtn{top:18px !important; left:16px !important;}
  #galaxyMap .galaxyTopTitle{top:22px !important; font-size:18px !important;}
  #galaxyMap .galaxyStatus{top:60px !important; width:calc(100vw - 36px) !important;}
}
@media (max-width: 430px){
  #menu .card{width:calc(100vw - 18px) !important; max-height:calc(100dvh - 18px);}
  #menu .menuActionRow{gap:10px;}
  #menu button{width:100%;}
  #galaxyMap .galaxyBackBtn{padding:8px 12px !important; font-size:10px !important;}
  #galaxyMap .galaxyStatus{padding:8px 10px !important; font-size:10px !important;}
  #galaxyMap .galaxyInfoPanel{border-radius:22px !important;}
}

/* ===== v75-step2-constellation-ui ===== */
:root{
  --v75-panel:linear-gradient(180deg, rgba(8,18,36,.95), rgba(4,10,20,.98));
  --v75-card:linear-gradient(180deg, rgba(9,19,38,.88), rgba(4,10,20,.93));
  --v75-line:rgba(72, 224, 255, .24);
  --v75-line-strong:rgba(102, 234, 255, .44);
  --v75-cyan:#67e8ff;
  --v75-cyan-strong:#1ddaff;
  --v75-purple:#a277ff;
  --v75-text:#eef9ff;
  --v75-sub:#a2c6dd;
  --v75-shadow:0 18px 42px rgba(2,6,23,.42), 0 0 20px rgba(6,182,255,.06);
}
/* STEP 2 ONLY: Constellation map UI */
#stageMap .stageBackBtn,
#stageMap .stageStatus,
#stageMap .stageInfoPanel,
#stageMap .stageEnter,
#stageMap #stageEnterBtn,
#stageMap .constellationCard,
#stageMap #stageHint{
  background:var(--v75-panel) !important;
  border:1px solid var(--v75-line) !important;
  box-shadow:inset 0 0 0 1px rgba(119,245,255,.03), var(--v75-shadow) !important;
}
#stageMap .stageBackBtn,
#stageMap .stageEnter,
#stageMap #stageEnterBtn,
#stageMap .constellationCard{
  color:var(--v75-text) !important;
}
#stageMap .stageBackBtn{
  top:24px !important;
  left:20px !important;
  padding:10px 14px !important;
  border-radius:18px !important;
  font-family:'Orbitron','Noto Sans KR',sans-serif !important;
}
#stageMap .stageTopTitle{
  top:26px !important;
  font-family:'Orbitron', Pretendard, sans-serif !important;
  font-size:clamp(18px, 2.4vw, 28px) !important;
  letter-spacing:.22em !important;
  color:var(--v75-cyan) !important;
  text-shadow:0 0 16px rgba(29,218,255,.12);
}
#stageMap .stageStatus{
  top:72px !important;
  border-radius:18px !important;
  padding:10px 14px !important;
  color:var(--v75-sub) !important;
  backdrop-filter:blur(10px);
}
#stageMap .stageStatus #stageProgressLabel{color:var(--v75-text) !important; font-family:'Orbitron',Pretendard,sans-serif !important; letter-spacing:.06em;}
#stageMap .stageStatus #stageProgressSub{color:var(--v75-sub) !important;}
#stageMap .stageMapInner{
  border:1px solid rgba(67,215,255,.16) !important;
  border-radius:28px !important;
  box-shadow:inset 0 0 0 1px rgba(119,245,255,.02), 0 0 18px rgba(6,182,255,.04) !important;
  overflow:hidden;
}
#stageMap .stageMapInner::before{
  content:''; position:absolute; inset:12px; pointer-events:none;
  border:1px solid rgba(67,215,255,.10); border-radius:22px;
  clip-path:polygon(0 16px, 16px 16px, 16px 0, calc(100% - 16px) 0, calc(100% - 16px) 16px, 100% 16px, 100% calc(100% - 16px), calc(100% - 16px) calc(100% - 16px), calc(100% - 16px) 100%, 16px 100%, 16px calc(100% - 16px), 0 calc(100% - 16px));
  opacity:.95;
}
#stageMap .constellationLabel{
  color:rgba(103,232,255,.70) !important;
  font-family:'Orbitron', Pretendard, sans-serif !important;
  letter-spacing:.22em !important;
  text-shadow:0 0 10px rgba(29,218,255,.08);
}
#stageMap .mapRouteBase{stroke:rgba(148,163,184,.16) !important;}
#stageMap .mapRouteLine{filter:drop-shadow(0 0 8px rgba(103,232,249,.16));}
#stageMap #constellationDeck{
  display:grid !important;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:12px !important;
}
#stageMap .constellationCard{
  background:var(--v75-card) !important;
  border-radius:18px !important;
  box-shadow:inset 0 0 0 1px rgba(119,245,255,.02), 0 0 14px rgba(6,182,255,.03) !important;
}
#stageMap .constellationCard .constellationKicker,
#stageMap .constellationCard small{color:var(--v75-cyan) !important;}
#stageMap .constellationCard b{color:var(--v75-text) !important; font-family:'Orbitron',Pretendard,sans-serif !important;}
#stageMap .constellationCard em{color:var(--v75-sub) !important;}
#stageMap .constellationCard .constellationMeta{color:#fde68a !important;}
#stageMap .constellationCard.active{border-color:rgba(102,234,255,.40) !important; box-shadow:inset 0 0 18px rgba(29,218,255,.06), 0 0 18px rgba(6,182,255,.08) !important;}
#stageMap .stageNode .nodeLabel,
#stageMap .stageNode .nodeKo,
#stageMap .stageNode .nodeNo,
#stageMap .stageNode .nodeLock{ text-shadow:0 0 10px rgba(0,0,0,.38); }
#stageMap .stageNode .nodeLabel{color:#f5fbff !important; font-family:'Orbitron',Pretendard,sans-serif !important; letter-spacing:.1em !important;}
#stageMap .stageNode .nodeKo{color:#caeaff !important;}
#stageMap #stageHint{
  background:rgba(6,15,30,.88) !important;
  color:var(--v75-sub) !important;
  border-radius:18px !important;
  padding:12px 14px !important;
}
#stageMap .stageInfoPanel{
  border-radius:26px !important;
  color:var(--v75-sub) !important;
}
#stageMap .stageInfoHead{
  border-bottom:1px solid rgba(67,215,255,.12) !important;
  padding-bottom:10px !important;
  margin-bottom:10px !important;
}
#stageMap .stageInfoTitle{
  font-family:'Orbitron', Pretendard, sans-serif !important;
  color:var(--v75-text) !important;
}
#stageMap .stageInfoRisk span,
#stageMap .stageTagRow > *{color:var(--v75-cyan) !important;}
#stageMap .stageInfoRisk b{color:var(--v75-text) !important;}
#stageMap .stageInfoMood{color:var(--v75-sub) !important;}
#stageMap .stageTagRow > *{
  background:var(--v75-card) !important;
  border:1px solid rgba(67,215,255,.16) !important;
  border-radius:999px !important;
  padding:6px 10px !important;
  box-shadow:inset 0 0 0 1px rgba(119,245,255,.02) !important;
}
#stageMap .stageBossCard,
#stageMap #offlineStagePanel{
  background:var(--v75-card) !important;
  border:1px solid rgba(67,215,255,.16) !important;
  border-radius:18px !important;
  box-shadow:inset 0 0 0 1px rgba(119,245,255,.02), 0 0 14px rgba(6,182,255,.03) !important;
}
#stageMap .stageBossCard small{color:var(--v75-cyan) !important; font-family:'Orbitron', Pretendard, sans-serif !important;}
#stageMap .stageBossCard b{color:var(--v75-text) !important;}
#stageMap .stageBossCard span,
#stageMap .stageBossCard em{color:var(--v75-sub) !important;}
#stageMap .stageEnter,
#stageMap #stageEnterBtn{
  background:linear-gradient(90deg, rgba(89,228,255,.98), rgba(108,118,255,.96), rgba(163,92,255,.96)) !important;
  color:white !important;
  border-color:rgba(215,243,255,.36) !important;
  box-shadow:inset 0 0 0 1px rgba(255,255,255,.16), 0 0 24px rgba(120,168,255,.18) !important;
  border-radius:18px !important;
  font-family:'Orbitron','Noto Sans KR',sans-serif !important;
  letter-spacing:.06em !important;
}
#stageMap .stageBackBtn:hover,
#stageMap .stageEnter:hover,
#stageMap #stageEnterBtn:hover,
#stageMap .constellationCard:hover{transform:translateY(-1px);}
@media (max-width: 980px){
  #stageMap #constellationDeck{grid-template-columns:1fr !important;}
}
@media (max-width: 768px){
  #stageMap .stageBackBtn{top:18px !important; left:16px !important;}
  #stageMap .stageTopTitle{top:22px !important; font-size:18px !important;}
  #stageMap .stageStatus{top:60px !important; width:calc(100vw - 36px) !important;}
  #stageMap .stageInfoPanel{border-radius:22px !important;}
}
@media (max-width: 430px){
  #stageMap .stageBackBtn{padding:8px 12px !important; font-size:10px !important;}
  #stageMap .stageStatus{padding:8px 10px !important; font-size:10px !important;}
  #stageMap .stageInfoPanel{border-radius:20px !important;}
}

/* ===== v76-step3-battle-hud-ui ===== */
:root{
  --v76-panel:linear-gradient(180deg, rgba(8,18,36,.95), rgba(4,10,20,.98));
  --v76-card:linear-gradient(180deg, rgba(9,19,38,.88), rgba(4,10,20,.93));
  --v76-line:rgba(72, 224, 255, .22);
  --v76-line-strong:rgba(102, 234, 255, .42);
  --v76-cyan:#67e8ff;
  --v76-cyan-strong:#1ddaff;
  --v76-purple:#a277ff;
  --v76-text:#eef9ff;
  --v76-sub:#a2c6dd;
  --v76-shadow:0 18px 42px rgba(2,6,23,.42), 0 0 20px rgba(6,182,255,.06);
}
/* STEP 3 ONLY: Battle HUD / command / selected / top-right icons */
#side.battleMinimal .battleHud,
#side.battleMinimal .battleActions,
#side.battleMinimal .battleSelected{
  background:var(--v76-panel) !important;
  border:1px solid var(--v76-line) !important;
  border-radius:26px !important;
  box-shadow:inset 0 0 0 1px rgba(119,245,255,.03), var(--v76-shadow) !important;
  position:relative;
  overflow:hidden;
}
#side.battleMinimal .battleHud::before,
#side.battleMinimal .battleActions::before,
#side.battleMinimal .battleSelected::before{
  content:'';
  position:absolute;
  inset:10px;
  pointer-events:none;
  border:1px solid rgba(67,215,255,.10);
  border-radius:18px;
  clip-path:polygon(0 14px, 14px 14px, 14px 0, calc(100% - 14px) 0, calc(100% - 14px) 14px, 100% 14px, 100% calc(100% - 14px), calc(100% - 14px) calc(100% - 14px), calc(100% - 14px) 100%, 14px 100%, 14px calc(100% - 14px), 0 calc(100% - 14px));
  opacity:.85;
}
#side.battleMinimal .battleHud{
  padding:18px 16px 16px !important;
}
#side.battleMinimal .battleStageLine{
  display:grid;
  grid-template-columns:minmax(0,1fr) auto;
  grid-template-areas:"theme stage" "sub stage";
  gap:4px 12px;
  align-items:center;
  padding-bottom:12px;
  margin-bottom:12px;
  border-bottom:1px solid rgba(67,215,255,.12);
}
#themeName{
  grid-area:theme;
  color:var(--v76-cyan) !important;
  font-family:'Orbitron', Pretendard, sans-serif !important;
  font-size:12px !important;
  letter-spacing:.16em !important;
  text-shadow:0 0 10px rgba(29,218,255,.10);
}
#stageType{
  grid-area:sub;
  color:var(--v76-sub) !important;
  font-size:13px !important;
}
#stageLabel{
  grid-area:stage;
  color:var(--v76-text) !important;
  font-family:'Orbitron', Pretendard, sans-serif !important;
  font-size:42px !important;
  line-height:1 !important;
  letter-spacing:-.03em !important;
  text-shadow:0 0 12px rgba(255,255,255,.06);
}
#wavePreviewLine,
#globalEffectLine{
  color:var(--v76-sub) !important;
  border:1px solid rgba(67,215,255,.10);
  background:rgba(8,18,36,.38) !important;
  border-radius:14px;
  padding:9px 10px;
}
#wavePreviewLine b,
#globalEffectLine b{
  color:var(--v76-cyan) !important;
  font-family:'Orbitron', Pretendard, sans-serif !important;
  margin-right:6px;
}
#side.battleMinimal .bar.compactWave,
#side.battleMinimal .miniBar{
  background:rgba(9,18,36,.92) !important;
  border:1px solid rgba(67,215,255,.10) !important;
  box-shadow:none !important;
}
#side.battleMinimal .bar > span,
#side.battleMinimal .miniBar > span{
  background:linear-gradient(90deg, #1fe0ff, #6d7dff, #ab72ff) !important;
  box-shadow:0 0 14px rgba(31,224,255,.16) !important;
}
#side.battleMinimal .battleStatLine.statGrid{
  gap:10px !important;
}
#side.battleMinimal .statGrid .stat{
  background:var(--v76-card) !important;
  border:1px solid rgba(67,215,255,.12) !important;
  border-radius:18px !important;
  box-shadow:inset 0 0 0 1px rgba(119,245,255,.02) !important;
}
#side.battleMinimal .stat .label{
  color:var(--v76-cyan) !important;
  font-family:'Orbitron', Pretendard, sans-serif !important;
  letter-spacing:.12em !important;
  font-size:11px !important;
}
#side.battleMinimal .stat .value{
  color:var(--v76-text) !important;
  font-family:'Orbitron', Pretendard, sans-serif !important;
}
#side.battleMinimal .battleActions{
