/* ===== v214-top-hud-proportional-edge-layout ===== */
/* v214: Top HUD proportional edge layout.
   All top HUD elements are grouped into one line. Only the left/right inset grows
   proportionally from the screen edges, so landscape/portrait no longer need
   separate hand-tuned top positions. */
#field{
  --hud-edge-x:clamp(14px, 3.2vw, 46px);
  --hud-edge-y:clamp(10px, 2.2vh, 24px);
  --hud-top-gap:clamp(10px, 2.4vw, 54px);
  --hud-item-gap:clamp(6px, 1.1vw, 13px);
}
#combatHudOverlay{
  position:absolute !important;
  inset:0 !important;
  width:100% !important;
  height:100% !important;
  display:block !important;
  pointer-events:none !important;
  z-index:32 !important;
}
#combatHudTopLine{
  position:absolute !important;
  top:var(--hud-edge-y) !important;
  left:var(--hud-edge-x) !important;
  right:var(--hud-edge-x) !important;
  width:auto !important;
  height:auto !important;
  display:flex !important;
  align-items:flex-start !important;
  justify-content:space-between !important;
  gap:var(--hud-top-gap) !important;
  pointer-events:none !important;
  z-index:44 !important;
}
#combatHudTopLine #combatHudLeft,
#combatHudTopLine #combatHudRight{
  position:relative !important;
  top:auto !important;
  left:auto !important;
  right:auto !important;
  bottom:auto !important;
  width:auto !important;
  height:auto !important;
  max-width:none !important;
  margin:0 !important;
  transform:none !important;
  pointer-events:none !important;
}
#combatHudTopLine #combatHudLeft{
  flex:0 0 clamp(170px, 22vw, 286px) !important;
  display:flex !important;
  align-items:flex-start !important;
  justify-content:flex-start !important;
  gap:var(--hud-item-gap) !important;
  min-width:0 !important;
}
#combatHudTopLine #combatHudRight{
  flex:1 1 auto !important;
  display:flex !important;
  align-items:flex-start !important;
  justify-content:flex-end !important;
  gap:var(--hud-item-gap) !important;
  min-width:0 !important;
}
#combatHudTopLine #combatHudMeta{
  flex:1 1 auto !important;
  width:100% !important;
  min-width:0 !important;
  display:flex !important;
  flex-direction:column !important;
  gap:clamp(4px, .7vw, 7px) !important;
}
#combatHudTopLine #combatHudStatsWrap{
  flex:0 1 auto !important;
  min-width:0 !important;
  display:flex !important;
  align-items:flex-start !important;
  justify-content:flex-end !important;
