/* ===== v75-stage-selected-background-full-cover-fix ===== */
/* v75: every selected stage background must fill the whole stage viewport.
   Previous late-stage biome layers (gravity/thunder/time/silent/rift) still had
   partial width/height offsets, so some clicked planets showed a clipped backdrop.
   This final override normalizes all 12 stage background layers to the same full-cover rule. */
#stageMap .stageBg,
#stageMap .stageBg.cosmic,
#stageMap .stageBg.frost,
#stageMap .stageBg.lava,
#stageMap .stageBg.jungle,
#stageMap .stageBg.smog,
#stageMap .stageBg.crystal,
#stageMap .stageBg.machine,
#stageMap .stageBg.gravity,
#stageMap .stageBg.thunder,
#stageMap .stageBg.time,
#stageMap .stageBg.silent,
#stageMap .stageBg.rift{
  position:absolute !important;
  inset:0 !important;
  left:0 !important;
  top:0 !important;
  right:0 !important;
  bottom:0 !important;
  width:100% !important;
  height:100% !important;
  min-width:100% !important;
  min-height:100% !important;
  max-width:none !important;
  max-height:none !important;
  background-size:cover !important;
  background-position:center center !important;
  background-repeat:no-repeat !important;
  transform:none !important;
  rotate:0deg !important;
  scale:1 !important;
  translate:0 0 !important;
  -webkit-mask-image:none !important;
  mask-image:none !important;
  mix-blend-mode:normal !important;
  pointer-events:none !important;
  opacity:0 !important;
  filter:brightness(.55) saturate(1.02) contrast(1.04) !important;
  transition:opacity .24s ease, filter .24s ease !important;
}

/* Re-declare all images after the offset reset so the browser uses the correct full-cover layer. */
#stageMap .stageBg.cosmic{background-image:url("../../assets/images/backgrounds/bg_cosmic.webp") !important;}
#stageMap .stageBg.frost{background-image:url("../../assets/images/backgrounds/bg_frost.webp") !important;}
#stageMap .stageBg.lava{background-image:url("../../assets/images/backgrounds/bg_lava.webp") !important;}
#stageMap .stageBg.jungle{background-image:url("../../assets/images/backgrounds/bg_jungle.webp") !important;}
#stageMap .stageBg.smog{background-image:url("../../assets/images/biomes/biome_smog_feather.webp") !important;}
#stageMap .stageBg.crystal{background-image:url("../../assets/images/biomes/biome_crystal_feather.webp") !important;}
#stageMap .stageBg.machine{background-image:url("../../assets/images/biomes/biome_machine_feather.webp") !important;}
#stageMap .stageBg.gravity{background-image:url("../../assets/images/biomes/biome_machine_feather.webp") !important;filter:hue-rotate(20deg) brightness(.55) saturate(.92) contrast(1.04) !important;}
#stageMap .stageBg.thunder{background-image:url("../../assets/images/biomes/biome_machine_feather.webp") !important;filter:hue-rotate(-24deg) brightness(.58) saturate(1.12) contrast(1.06) !important;}
#stageMap .stageBg.time{background-image:url("../../assets/images/biomes/biome_crystal_feather.webp") !important;filter:hue-rotate(18deg) brightness(.58) saturate(1.04) contrast(1.06) !important;}
#stageMap .stageBg.silent{background-image:url("../../assets/images/biomes/biome_smog_feather.webp") !important;filter:hue-rotate(-8deg) brightness(.52) saturate(.78) contrast(1.06) !important;}
#stageMap .stageBg.rift{background-image:url("../../assets/images/biomes/biome_crystal_feather.webp") !important;filter:hue-rotate(128deg) brightness(.52) saturate(1.14) contrast(1.08) !important;}

/* Exactly one full-screen background is visible per selected sanctuary. */
#stageMap[data-selected="1"] .stageBg.cosmic,
